export type MutationFamily =
  | "Structural"
  | "Metabolic"
  | "Neural"
  | "Cross-Species"
  | "Elemental"
  | "Defensive"
  | "Offensive"
  | "Mobility"
  | "Wildcard";

export type MutationRarity =
  | "Common"
  | "Uncommon"
  | "Rare"
  | "Epic"
  | "Legendary";

export type MutationDefinition = {
  id: string;
  name: string;
  family: MutationFamily;
  rarity: MutationRarity;
  description: string;
  visualEffect: string;
  statBias: {
    health: number;
    attack: number;
    defense: number;
    speed: number;
  };
  movePowerMultiplier: number;
  tags: string[];
  evolutionInfluence: string;
};

