export const MUTATIONS_BY_ID = new Map(
  MUTATIONS.map((mutation) => [mutation.id, mutation]),
);

export function getMutation(id: string): MutationDefinition | undefined {
  return MUTATIONS_BY_ID.get(id);
}

export function getMutationsByFamily(
  family: MutationFamily,
): MutationDefinition[] {
  return MUTATIONS.filter((mutation) => mutation.family === family);
}

export function getMutationsByRarity(
  rarity: MutationRarity,
): MutationDefinition[] {
  return MUTATIONS.filter((mutation) => mutation.rarity === rarity);
}

export function searchMutations(query: string): MutationDefinition[] {
  const normalized = query.trim().toLowerCase();

  if (!normalized) return MUTATIONS;

  return MUTATIONS.filter((mutation) =>
    mutation.name.toLowerCase().includes(normalized) ||
    mutation.family.toLowerCase().includes(normalized) ||
    mutation.description.toLowerCase().includes(normalized) ||
    mutation.tags.some((tag) => tag.toLowerCase().includes(normalized))
  );
}

const RARITY_WEIGHTS: Record<MutationRarity, number> = {
  Common: 38,
  Uncommon: 28,
  Rare: 18,
  Epic: 10,
  Legendary: 6,
};

function hashSeed(seed: string): number {
  let hash = 2166136261;

  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }

  return hash >>> 0;
}

function seededUnit(seed: string): number {
  let x = hashSeed(seed);
  x ^= x << 13;
  x ^= x >>> 17;
  x ^= x << 5;
  return (x >>> 0) / 4294967296;
}

export function rollMutation(
  seed: string,
  options?: {
    family?: MutationFamily;
    excludeIds?: string[];
    allowWildcard?: boolean;
  },
): MutationDefinition {
  const excluded = new Set(options?.excludeIds ?? []);

  let pool = MUTATIONS.filter((mutation) => !excluded.has(mutation.id));

  if (options?.family) {
    pool = pool.filter((mutation) => mutation.family === options.family);
  }

  if (options?.allowWildcard === false) {
    pool = pool.filter((mutation) => mutation.family !== "Wildcard");
  }

  if (!pool.length) {
    throw new Error("No mutations available for the requested roll.");
  }

  const weightedPool = pool.map((mutation) => ({
    mutation,
    weight: RARITY_WEIGHTS[mutation.rarity],
  }));

  const totalWeight = weightedPool.reduce(
    (sum, item) => sum + item.weight,
    0,
  );

  let roll = seededUnit(seed) * totalWeight;

  for (const item of weightedPool) {
    roll -= item.weight;

    if (roll <= 0) {
      return item.mutation;
    }
  }

  return weightedPool[weightedPool.length - 1].mutation;
}

export function rollMutationSet(
  seed: string,
  count: number,
  options?: {
    allowWildcard?: boolean;
  },
): MutationDefinition[] {
  const results: MutationDefinition[] = [];

  for (let index = 0; index < count; index += 1) {
    results.push(
      rollMutation(`${seed}:${index}`, {
        excludeIds: results.map((item) => item.id),
        allowWildcard: options?.allowWildcard,
      }),
    );
  }

  return results;
}

export const MUTATION_COUNT = MUTATIONS.length;
